#!/usr/bin/env python3
"""Две записи настроек одновременно — и права, которые от записи не растут.

Сценарии пришли из внешней проверки и переписаны здесь регрессионными тестами
ПРАВИЛЬНОГО поведения. Проверка нашла три дефекта в четырёх строках записи
настроек, и все три выглядели работающим кодом:

  · имя временного файла было одно на всех. Два процесса, пишущих
    `settings.json`, брали один и тот же `settings.json.tmp`: один падал «нет
    такого файла», и одна из двух настроек пропадала — при этом обе операции
    завершились и обе вернули ноль;
  · атомарной замены мало. Оба процесса читают старое состояние, каждый меняет
    СВОЮ часть и пишет ЦЕЛИКОМ; записавший вторым затирает чужую правку. Дыра
    не в записи, а МЕЖДУ чтением и записью, и закрывает её только замок,
    который держится весь цикл;
  · замена файла не наследует режим доступа. Файл с правами 0600 после записи
    получал 0644 при обычном umask 022 — то есть настройки человека
    становились читаемыми другим локальным пользователям машины.

Что здесь заперто:

  · две одновременные записи разных настроек не теряют ни одной молча;
  · существовавший файл сохраняет свой режим, новый создаётся приватным;
  · у ожидания замка есть предел, и его превышение говорится словами;
  · обратный контроль: обычная одиночная запись работает как прежде.

Одновременность здесь настоящая: два потока операционной системы, сведённые
барьером, и разрыв между чтением и записью, открытый нарочно. Без разрыва
проверка зависела бы от того, кто из потоков успел первым, — то есть отвечала
бы разное на неизменном коде.

Тест самодостаточен: только стандартная библиотека и сами инструменты.
"""
from __future__ import annotations

import contextlib
import importlib.util
import io
import json
import os
import stat
import sys
import tempfile
import threading
import time
import unittest
from pathlib import Path

РЕПО = Path(__file__).resolve().parents[2]
ИНСТРУМЕНТЫ = РЕПО / "plugins" / "superstack" / "tools"

# Каталог инструментов в пути: общий модуль записи соседи импортируют по
# имени, и без этого apply.py не загрузится вовсе.
if str(ИНСТРУМЕНТЫ) not in sys.path:
    sys.path.insert(0, str(ИНСТРУМЕНТЫ))


def _загрузить(имя: str, файл: Path):
    спек = importlib.util.spec_from_file_location(имя, файл)
    мод = importlib.util.module_from_spec(спек)
    # Имя настоящее, а не выдуманное: apply.py импортирует общий модуль сам, и
    # два его экземпляра в одном процессе разошлись бы состоянием — например
    # отметкой «про отсутствие замка уже сказано».
    sys.modules[имя] = мод
    спек.loader.exec_module(мод)
    return мод


хранилище = _загрузить("atomic_store", ИНСТРУМЕНТЫ / "atomic_store.py")
применение = _загрузить("ss_apply_concurrent", ИНСТРУМЕНТЫ / "apply.py")

#: Почему часть проверок не имеет смысла вне POSIX. Пропуск НАЗЫВАЕТСЯ: молча
#: пропущенная проверка читается как пройденная, а это разные утверждения.
ПОЧЕМУ_POSIX = ("права файла и запирание области файла — понятия POSIX: на "
                "Windows доступ выражается списком прав, а замок берётся другим "
                "вызовом. Пропуск назван вслух, чтобы «не проверяли» не "
                "читалось как «прошло»")
ТОЛЬКО_POSIX = unittest.skipUnless(os.name == "posix", ПОЧЕМУ_POSIX)


class Настройки(unittest.TestCase):
    """Дом на время проверки: инструмент пишет в настройки человека."""

    #: Разрыв между чтением и записью. Столько времени состояние прочитано, но
    #: ещё не записано, — ровно окно, в которое влезает второй процесс.
    ОКНО = 0.05

    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        дом = Path(tmp.name)
        self.claude = дом / ".claude"
        self.claude.mkdir(parents=True)
        было = (применение.HOME, применение.CLAUDE, применение.STATE,
                применение.BACKUPS, применение.QUARANTINE)

        def вернуть_дом():
            (применение.HOME, применение.CLAUDE, применение.STATE,
             применение.BACKUPS, применение.QUARANTINE) = было

        self.addCleanup(вернуть_дом)
        применение.HOME = дом
        применение.CLAUDE = self.claude
        применение.STATE = self.claude / "superstack"
        применение.BACKUPS = применение.STATE / "backups"
        применение.QUARANTINE = применение.STATE / "quarantine"
        self.файл = self.claude / "settings.json"

    def разорвать_цикл(self) -> None:
        """Задержать ЗАПИСЬ, оставив чтение на месте.

        Так разрыв «прочитал → записал» становится измеримым, а не
        микросекундным: без него исход зависел бы от планировщика потоков, и
        один и тот же код отвечал бы то так, то иначе.
        """
        настоящая = применение._write_json

        def медленно(path, data):
            time.sleep(self.ОКНО)
            настоящая(path, data)

        применение._write_json = медленно
        self.addCleanup(setattr, применение, "_write_json", настоящая)

    def режим(self) -> int:
        return stat.S_IMODE(self.файл.stat().st_mode)


class ДвеЗаписиОдновременно(Настройки):
    """Волна из двух помощников — это два процесса, пишущих один файл."""

    @ТОЛЬКО_POSIX
    def test_ни_одна_из_двух_настроек_не_пропадает(self):
        """Обе переживают — либо одна получает ЯВНЫЙ отказ.

        Молчаливая потеря запрещена в любом случае: запись, объявившая себя
        сделанной, обязана быть на диске. Здесь предел ожидания замка много
        больше разрыва, поэтому законный исход ровно один — обе на месте.
        """
        self.разорвать_цикл()
        барьер = threading.Barrier(2, timeout=30)
        итоги, беды = {}, []

        def пишет(ключ, значение):
            try:
                барьер.wait()
                итоги[ключ] = применение._set_setting(ключ, значение, False)
            except BaseException as e:                       # noqa: BLE001
                беды.append(f"{ключ}: {e!r}")

        потоки = [threading.Thread(target=пишет, args=(к, з))
                  for к, з in (("перваяНастройка", 1), ("втораяНастройка", 2))]
        for п in потоки:
            п.start()
        for п in потоки:
            п.join(timeout=60)

        self.assertEqual([п.name for п in потоки if п.is_alive()], [],
                         "поток не вернулся — запись зависла")
        self.assertEqual(беды, [], "запись настройки упала")

        стало = json.loads(self.файл.read_text("utf-8"))
        объявлено = {к for к, r in итоги.items() if r.get("changed")}
        self.assertEqual(sorted(объявлено - set(стало)), [],
                         "запись объявлена сделанной, а на диске её нет — "
                         "ровно та молчаливая потеря, ради которой замок")
        self.assertEqual(объявлено, {"перваяНастройка", "втораяНастройка"},
                         "одна из настроек не записалась и не отказала явно")
        self.assertEqual(стало["перваяНастройка"], 1)
        self.assertEqual(стало["втораяНастройка"], 2)

    @ТОЛЬКО_POSIX
    def test_чужая_настройка_переживает_обе_записи(self):
        """Лежавшее в файле до нас не должно исчезать ни при каком порядке."""
        self.файл.write_text(json.dumps({"чужое": "не трогать"}),
                             encoding="utf-8")
        self.разорвать_цикл()
        барьер = threading.Barrier(2, timeout=30)

        def пишет(ключ):
            барьер.wait()
            применение._set_setting(ключ, True, False)

        потоки = [threading.Thread(target=пишет, args=(к,))
                  for к in ("одна", "другая")]
        for п in потоки:
            п.start()
        for п in потоки:
            п.join(timeout=60)

        стало = json.loads(self.файл.read_text("utf-8"))
        self.assertEqual(стало.get("чужое"), "не трогать",
                         "запись затёрла то, чего не писала")


class ПраваНеРастут(Настройки):
    """Настройки человека не становятся читаемыми соседям по машине."""

    def setUp(self):
        super().setUp()
        # Тот самый обычный umask, при котором 0600 превращался в 0644.
        прежний = os.umask(0o022)
        self.addCleanup(os.umask, прежний)

    @ТОЛЬКО_POSIX
    def test_файл_0600_остаётся_0600(self):
        self.файл.write_text("{}", encoding="utf-8")
        os.chmod(self.файл, 0o600)
        r = применение._set_setting("ключ", True, False)
        self.assertTrue(r["changed"], "записи не было — проверять нечего")
        self.assertEqual(oct(self.режим()), oct(0o600),
                         "запись расширила права: файл стал читаем другим "
                         "локальным пользователям")

    @ТОЛЬКО_POSIX
    def test_файл_0644_остаётся_0644(self):
        """Обратная половина того же правила: режим СОХРАНЯЕТСЯ, а не
        назначается заново. Всегда запирать чужой файл — тоже менять решение
        человека, просто в другую сторону."""
        self.файл.write_text("{}", encoding="utf-8")
        os.chmod(self.файл, 0o644)
        применение._set_setting("ключ", True, False)
        self.assertEqual(oct(self.режим()), oct(0o644),
                         "запись переназначила режим существовавшего файла")

    @ТОЛЬКО_POSIX
    def test_новый_файл_настроек_приватен_а_не_по_umask(self):
        self.assertFalse(self.файл.exists(), "файла быть не должно")
        применение._set_setting("ключ", True, False)
        self.assertEqual(oct(self.режим()), oct(0o600),
                         "новый файл настроек создан по umask, то есть "
                         "читаемым другим локальным пользователям")


class ВременныйСоседСвойУКаждойЗаписи(Настройки):
    """Общее имя `.tmp` два процесса отбирали друг у друга."""

    def test_две_записи_берут_разные_временные_имена(self):
        первый = хранилище._временный(self.файл)
        второй = хранилище._временный(self.файл)
        self.addCleanup(первый.unlink)
        self.addCleanup(второй.unlink)
        self.assertNotEqual(первый, второй,
                            "временное имя одно на всех: второй процесс "
                            "отбирает файл у первого")
        self.assertEqual(первый.parent, self.файл.parent,
                         "временный сосед не рядом с целью — переименование "
                         "перестанет быть атомарным на другом разделе")

    @ТОЛЬКО_POSIX
    def test_временный_сосед_создаётся_приватным(self):
        прежний = os.umask(0o022)
        self.addCleanup(os.umask, прежний)
        врем = хранилище._временный(self.файл)
        self.addCleanup(врем.unlink)
        self.assertEqual(oct(stat.S_IMODE(врем.stat().st_mode)), oct(0o600),
                         "содержимое настроек лежит рядом открытым, пока идёт "
                         "запись")


class ОжиданиеЗамкаИмеетПредел(Настройки):
    """Замок, которого не досталось, — это состояние, а не вечное ожидание."""

    @ТОЛЬКО_POSIX
    def test_занятый_замок_даёт_названный_отказ_а_не_виснет(self):
        хранилище._БЕЗ_ЗАМКА_СКАЗАНО = False
        self.addCleanup(setattr, хранилище, "_БЕЗ_ЗАМКА_СКАЗАНО", False)
        речь = io.StringIO()
        итог = {}

        def второй():
            with contextlib.redirect_stderr(речь):
                with хранилище.Lock(self.файл, ждать=0.05) as з:
                    итог["заперто"] = з.заперто

        with хранилище.Lock(self.файл) as первый:
            self.assertTrue(первый.заперто,
                            "первый замок не взят — проверять нечего")
            поток = threading.Thread(target=второй)
            начало = time.monotonic()
            поток.start()
            поток.join(timeout=20)
            прошло = time.monotonic() - начало

        self.assertFalse(поток.is_alive(),
                         "ожидание замка не кончилось: запись висит молча, без "
                         "ошибки и без признака поломки")
        self.assertIs(итог.get("заперто"), False,
                      "занятый замок объявлен взятым")
        self.assertLess(прошло, 10,
                        "ожидание вышло далеко за собственный предел")
        сказано = речь.getvalue()
        self.assertIn("без замка", сказано,
                      "отказ по замку прошёл молча — работа без замка обязана "
                      "быть названа вслух")


class ОдиночнаяЗаписьРаботаетКакПрежде(Настройки):
    """Обратный контроль. Починка одновременности не имеет права поменять
    поведение там, где никакой одновременности нет."""

    def test_настройка_записывается_и_соседние_поля_целы(self):
        self.файл.write_text(json.dumps({"чужое": {"вложенное": [1, 2]}},
                                        ensure_ascii=False), encoding="utf-8")
        r = применение._set_setting("новое", "значение", False)
        self.assertTrue(r["changed"])
        стало = json.loads(self.файл.read_text("utf-8"))
        self.assertEqual(стало["новое"], "значение")
        self.assertEqual(стало["чужое"], {"вложенное": [1, 2]})

    def test_существующее_значение_не_перезаписывается(self):
        self.файл.write_text(json.dumps({"ключ": "моё"}), encoding="utf-8")
        r = применение._set_setting("ключ", "чужое", False)
        self.assertFalse(r["changed"], "решение человека переписано")
        self.assertEqual(json.loads(self.файл.read_text("utf-8"))["ключ"], "моё")

    def test_черновой_прогон_ничего_не_пишет(self):
        r = применение._set_setting("ключ", True, True)
        self.assertTrue(r["changed"])
        self.assertFalse(self.файл.exists(), "черновой прогон записал файл")

    def test_временных_файлов_рядом_не_остаётся(self):
        применение._set_setting("ключ", True, False)
        мусор = sorted(p.name for p in self.claude.iterdir()
                       if p.name.endswith(".tmp"))
        self.assertEqual(мусор, [],
                         "временный сосед остался лежать рядом с настройками")


if __name__ == "__main__":
    unittest.main()
